<?php
namespace Tests\Feature;
use App\Jobs\SendApplicantNotification;use App\Models\{AdmissionPeriod,Applicant};use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Queue;use Tests\TestCase;
class ApplicantStatusNotificationTest extends TestCase {use RefreshDatabase;public function test_every_status_change_queues_email_and_whatsapp():void{Queue::fake();$period=AdmissionPeriod::create(['name'=>'Aktif','year'=>2026,'registration_prefix'=>'PKU','starts_at'=>now()->subDay(),'ends_at'=>now()->addDay(),'registration_fee'=>250000,'is_active'=>true]);$applicant=Applicant::create(['admission_period_id'=>$period->id,'registration_number'=>'PKU-2026-009999','submission_uuid'=>fake()->uuid(),'full_name'=>'Pendaftar Notifikasi','birth_place'=>'Jakarta','birth_date'=>'2000-01-01','address'=>'Alamat','whatsapp_normalized'=>'6281234567890','whatsapp_display'=>'081234567890','email'=>'notify@example.test','payment_status'=>'unpaid','document_status'=>'pending_review','selection_status'=>'not_scheduled','consented_at'=>now(),'submitted_at'=>now()]);$applicant->update(['payment_status'=>'pending']);$this->assertDatabaseHas('notification_logs',['applicant_id'=>$applicant->id,'event_type'=>'payment_pending','channel'=>'email']);$this->assertDatabaseHas('notification_logs',['applicant_id'=>$applicant->id,'event_type'=>'payment_pending','channel'=>'whatsapp']);Queue::assertPushed(SendApplicantNotification::class,2);}}
